    38|  const possiblePaths = [];
    39|  const platform = os.platform();
    40|
    41|  if (platform === 'darwin') {
    42|    const home = os.homedir();
    43|    possiblePaths.push(
    44|      path.join(home, 'Library/Application Support/Google/Chrome/DevToolsActivePort'),
    45|      path.join(home, 'Library/Application Support/Google/Chrome Canary/DevToolsActivePort'),
    46|      path.join(home, 'Library/Application Support/Chromium/DevToolsActivePort'),
    47|    );
    48|  } else if (platform === 'linux') {
    49|    const home = os.homedir();
    50|    possiblePaths.push(
    51|      path.join(home, '.config/google-chrome/DevToolsActivePort'),
    52|      path.join(home, '.config/chromium/DevToolsActivePort'),
    53|    );
    54|  } else if (platform === 'win32') {
    55|    const localAppData = process.env.LOCALAPPDATA || '';
    56|    possiblePaths.push(
    57|      path.join(localAppData, 'Google/Chrome/User Data/DevToolsActivePort'),
    58|      path.join(localAppData, 'Chromium/User Data/DevToolsActivePort'),
    59|    );
    60|  }
    61|
    62|  for (const p of possiblePaths) {
    63|    try {
    64|      const content = fs.readFileSync(p, 'utf-8').trim();
    65|      const lines = content.split('\n');
    66|      const port = parseInt(lines[0]);
    67|      if (port > 0 && port < 65536) {
    68|        const ok = await checkPort(port);
    69|        if (ok) {
