    71|          // 非显式 --remote-debugging-port 启动时，Chrome 可能只接受此路径
    72|          const wsPath = lines[1] || null;
    73|          console.log(`[CDP Proxy] 从 DevToolsActivePort 发现端口: ${port}${wsPath ? ' (带 wsPath)' : ''}`);
    74|          return { port, wsPath };
    75|        }
    76|      }
    77|    } catch { /* 文件不存在，继续 */ }
    78|  }
