    93|// 用 TCP 探测端口是否监听——避免 WebSocket 连接触发 Chrome 安全弹窗
    94|// （WebSocket 探测会被 Chrome 视为调试连接，弹出授权对话框）
    95|function checkPort(port) {
    96|  return new Promise((resolve) => {
    97|    const socket = net.createConnection(port, '127.0.0.1');
    98|    const timer = setTimeout(() => { socket.destroy(); resolve(false); }, 2000);
    99|    socket.once('connect', () => { clearTimeout(timer); socket.destroy(); resolve(true); });
