   176|      ws.removeEventListener?.('error', onError);
   177|    }
   178|
   179|    // 兼容 Node 原生 WebSocket 和 ws 模块的事件 API
   180|    if (ws.on) {
   181|      ws.on('open', onOpen);
   182|      ws.on('error', onError);
   183|      ws.on('close', onClose);
   184|      ws.on('message', onMessage);
   185|    } else {
