   194|function sendCDP(method, params = {}, sessionId = null) {
   195|  return new Promise((resolve, reject) => {
   196|    if (!ws || (ws.readyState !== WS.OPEN && ws.readyState !== 1)) {
   197|      return reject(new Error('WebSocket 未连接'));
   198|    }
   199|    const id = ++cmdId;
   200|    const msg = { id, method, params };
   201|    if (sessionId) msg.sessionId = sessionId;
   202|    const timer = setTimeout(() => {
   203|      pending.delete(id);
   204|      reject(new Error('CDP 命令超时: ' + method));
   205|    }, 30000);
   206|    pending.set(id, { resolve, timer });
   207|    ws.send(JSON.stringify(msg));
   208|  });
